import React from 'react';

const AboutCard = ({ person }) => {
  const { title, bio, pic, link } = person;

  return (
    <article className="host-card">
      <img
        className="host-card__image"
        src={pic}
        alt={title}
        loading="eager"
        decoding="async"
      />
      <div className="host-card__content">
        <h3>{title}</h3>
        <p className="host-card__bio">{bio}</p>
        <a className="host-card__contact" href={`mailto:${link}`}>
          Contact {title}
        </a>
      </div>
    </article>
  );
};

export default AboutCard;
