import { useEffect, useState } from 'react';
import { HiMenuAlt4, HiX } from 'react-icons/hi';
import { NavLink } from 'react-router-dom';
import './Navigation.scss';

const Navigation = () => {
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    if (!menuOpen) return undefined;

    const closeOnEscape = (event) => {
      if (event.key === 'Escape') setMenuOpen(false);
    };

    document.addEventListener('keydown', closeOnEscape);
    return () => document.removeEventListener('keydown', closeOnEscape);
  }, [menuOpen]);

  const closeMenu = () => setMenuOpen(false);

  return (
    <header className="site-header">
      <nav className="site-nav content-wrap" aria-label="Main navigation">
        <NavLink className="site-brand" to="/" onClick={closeMenu}>
          <span className="site-brand__name">A Trop Rockin’ Christmas</span>
          <span className="site-brand__sponsor">
            Presented by Prestige Travel Vacations
          </span>
        </NavLink>

        <button
          className="site-nav__toggle"
          type="button"
          aria-label={menuOpen ? 'Close navigation menu' : 'Open navigation menu'}
          aria-expanded={menuOpen}
          aria-controls="primary-navigation"
          onClick={() => setMenuOpen((isOpen) => !isOpen)}
        >
          {menuOpen ? <HiX aria-hidden="true" /> : <HiMenuAlt4 aria-hidden="true" />}
        </button>

        <div
          className={`site-nav__links${menuOpen ? ' is-open' : ''}`}
          id="primary-navigation"
        >
          <NavLink end to="/" onClick={closeMenu}>
            Home
          </NavLink>
          <NavLink to="/about" onClick={closeMenu}>
            About the show
          </NavLink>
        </div>
      </nav>
    </header>
  );
};

export default Navigation;
